			switch(m) {
			case 0: return  0.0; /* atan(+...,+INF) */
			case 1: return -0.0; /* atan(-...,+INF) */
			case 2: return  kama__musl_atan2__pi;  /* atan(+...,-INF) */
			case 3: return -kama__musl_atan2__pi;  /* atan(-...,-INF) */
			}
